// src/pages/StudentDashboard.jsx
import { useState, useEffect, useContext } from "react";
import { useNavigate } from "react-router-dom";
import axios from "axios";
import { AuthContext } from "../contexts/AuthContext";

// Axios instance for /api/candidates
const api = axios.create({
  baseURL: "http://localhost:4000/api/candidates",
  withCredentials: true, // ensure cookies/JWT are sent
});

// Reusable Card Component
const Card = ({ title, children }) => (
  <div
    style={{
      background: "#fff",
      padding: "20px",
      borderRadius: "12px",
      boxShadow: "0 4px 12px rgba(0,0,0,0.08)",
      marginBottom: "20px",
    }}
  >
    <h2 style={{ marginBottom: "15px", color: "#007bff" }}>{title}</h2>
    {children}
  </div>
);

export default function StudentDashboard() {
  const [sidebarOpen, setSidebarOpen] = useState(true);
  const [activeTab, setActiveTab] = useState("Candidates");

  const [candidates, setCandidates] = useState([]);
  const [results, setResults] = useState({});
  const [winners, setWinners] = useState({});
  const [elections, setElections] = useState([]);
  const [selectedElection, setSelectedElection] = useState(null);
  const [myCandidacy, setMyCandidacy] = useState(null);

  const { logout } = useContext(AuthContext);
  const navigate = useNavigate();

  const statusStyle = (bgColor, textColor) => ({
    backgroundColor: bgColor,
    color: textColor,
    padding: "4px 10px",
    borderRadius: "6px",
    fontWeight: "bold",
    fontSize: "0.9rem",
  });

  const handleApiError = (err) => {
    console.error(err);
    if (err.response?.status === 401) {
      logout();
      navigate("/login");
    }
  };

  // ----------------------
  // API Calls
  // ----------------------
  const fetchCandidates = async () => {
    try {
      const res = await api.get("/");
      setCandidates(res.data);
    } catch (err) {
      handleApiError(err);
    }
  };

  const fetchMyCandidacy = async () => {
    try {
      const res = await api.get("/my-candidacy");
      if (res.data.status === "none") {
        setMyCandidacy(null);
      } else {
        setMyCandidacy({
          ...res.data,
          status:
            res.data.approved === null
              ? "pending"
              : res.data.approved
              ? "approved"
              : "rejected",
        });
      }
    } catch (err) {
      handleApiError(err);
    }
  };

  const reapplyCandidacy = async () => {
    if (!myCandidacy) return;

    try {
      const res = await api.post("/reapply", { id: myCandidacy.id });
      console.log("Reapply response:", res.data);

      setMyCandidacy((prev) => ({
        ...prev,
        status: "pending",
        rejectionComment: null,
      }));
    } catch (err) {
      console.error("Failed to reapply:", err.response?.data || err.message);
      handleApiError(err);
    }
  };

  useEffect(() => {
    fetchCandidates();
    fetchMyCandidacy();
  }, []);

  // ----------------------
  // Render Content
  // ----------------------
  const renderContent = () => {
    switch (activeTab) {
      case "Candidates":
        return (
          <Card title="Approved Candidates">
            {candidates.length === 0 ? (
              <p>No candidates yet.</p>
            ) : (
              <table style={{ width: "100%", borderCollapse: "collapse" }}>
                <thead>
                  <tr style={{ background: "#f1f1f1" }}>
                    <th style={{ padding: "8px" }}>Name</th>
                    <th style={{ padding: "8px" }}>Position</th>
                    <th style={{ padding: "8px" }}>Party</th>
                  </tr>
                </thead>
                <tbody>
                  {candidates.map((c) => (
                    <tr key={c.id} style={{ borderTop: "1px solid #eee" }}>
                      <td style={{ padding: "8px" }}>{c.name}</td>
                      <td style={{ padding: "8px" }}>{c.position}</td>
                      <td style={{ padding: "8px" }}>{c.party || "-"}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            )}
          </Card>
        );

      case "RegisterCandidacy":
        return (
          <Card title="My Candidacy Status">
            {!myCandidacy ? (
              <p>You haven’t filed for candidacy yet.</p>
            ) : (
              <>
                <p>
                  <strong>Position:</strong> {myCandidacy.position}
                </p>
                <p>
                  <strong>Status:</strong>{" "}
                  {myCandidacy.status === "pending" && (
                    <span style={statusStyle("#ffc107", "#000")}>Pending</span>
                  )}
                  {myCandidacy.status === "approved" && (
                    <span style={statusStyle("#28a745", "#fff")}>Approved</span>
                  )}
                  {myCandidacy.status === "rejected" && (
                    <span style={statusStyle("#dc3545", "#fff")}>Rejected</span>
                  )}
                </p>

                {myCandidacy.status === "rejected" &&
                  myCandidacy.rejectionComment && (
                    <>
                      <p style={{ color: "#dc3545", marginTop: "10px" }}>
                        <strong>Admin Comments:</strong>{" "}
                        {myCandidacy.rejectionComment}
                      </p>
                      <button
                        onClick={reapplyCandidacy}
                        style={{
                          marginTop: "10px",
                          padding: "8px 16px",
                          background: "#ffc107",
                          color: "#000",
                          border: "none",
                          borderRadius: "6px",
                          cursor: "pointer",
                          fontWeight: "bold",
                        }}
                      >
                        Reapply
                      </button>
                    </>
                  )}

                {myCandidacy.status !== "pending" && (
                  <button
                    onClick={() => navigate("/register-candidacy")}
                    style={{
                      marginTop: "15px",
                      padding: "10px 20px",
                      background: "#007bff",
                      border: "none",
                      borderRadius: "6px",
                      color: "#fff",
                      cursor: "pointer",
                    }}
                  >
                    Go to Registration Form
                  </button>
                )}
              </>
            )}
          </Card>
        );

      default:
        return null;
    }
  };

  return (
    <div
      style={{
        display: "flex",
        minHeight: "100vh",
        fontFamily: "Arial, sans-serif",
        background: "#f4f6f8",
      }}
    >
      {/* Sidebar */}
      <aside
        style={{
          width: sidebarOpen ? "220px" : "60px",
          background: "#343a40",
          color: "#fff",
          transition: "width 0.3s",
          paddingTop: "20px",
        }}
      >
        <button
          onClick={() => setSidebarOpen(!sidebarOpen)}
          style={{
            background: "none",
            border: "none",
            color: "#fff",
            fontSize: "1.5rem",
            cursor: "pointer",
            marginLeft: sidebarOpen ? "180px" : "10px",
          }}
        >
          ☰
        </button>
        <nav
          style={{
            marginTop: "30px",
            display: "flex",
            flexDirection: "column",
            gap: "15px",
            paddingLeft: sidebarOpen ? "20px" : "5px",
          }}
        >
          <span
            style={{ cursor: "pointer" }}
            onClick={() => setActiveTab("Candidates")}
          >
            👤 Candidates
          </span>
          <span
            style={{ cursor: "pointer" }}
            onClick={() => setActiveTab("RegisterCandidacy")}
          >
            📝 Register Candidacy
          </span>
          <button
            onClick={() => {
              logout();
              navigate("/login");
            }}
            style={{
              marginTop: "auto",
              background: "#dc3545",
              color: "#fff",
              border: "none",
              padding: "10px",
              borderRadius: "6px",
              cursor: "pointer",
              fontWeight: "bold",
            }}
          >
            Logout
          </button>
        </nav>
      </aside>

      {/* Main */}
      <main
        style={{
          flexGrow: 1,
          padding: "30px",
          maxWidth: "1000px",
          margin: "0 auto",
        }}
      >
        {renderContent()}
      </main>
    </div>
  );
}
